{"code":"def transform(grid):
    def runs(row):
        out=[]; s=0
        for i in range(1,len(row)+1):
            if i==len(row) or row[i]!=row[s]:
                out.append((i-s,s,i-1,row[s])); s=i
        return out
    cand=[]
    for i,r in enumerate(grid):
        cand += [(n,i,a,b,c) for n,a,b,c in runs(r) if n>=max(10,len(r)//2)]
    n,top,left,right,color=max(cand)
    # use earliest matching long horizontal border with same geometry
    matches=[i for nn,i,a,b,c in cand if a==left and b==right and c==color]
    top=min(matches); bottom=max(matches)
    return [r[left+1:right] for r in grid[top+1:bottom]]"}

